using Godot;
using System;
using System.Collections.Generic;

public partial class TransformationWorkspaceOperations
{
    private void Menu(Control owner,string title,string[] options,Action<string> callback){var popup=Attach(owner,new PopupPanel());var list=Attach(popup,new VBoxContainer {CustomMinimumSize=new Vector2(260,0)});Caption(list,title);foreach(string option in options)Action(list,option,()=>{popup.Hide();callback(option);});popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered();}
    public void state_menu(Control owner)
    {
        Menu(owner,"STATES",new[]{"Rename","Delete state and its keys","Copy state","Paste as new state","Move state up","Move state down"},value=>{var session=Session(owner);var item=session.Call("primary").As<Resource>();var state=Active(owner);if(item==null||state==null)return;switch(value){case "Rename":var name=Item<LineEdit>(owner,"_state_name");if(GodotObject.IsInstanceValid(name)){name.GrabFocus();name.SelectAll();}break;case "Delete state and its keys":session.Call("delete_state");break;case "Copy state":session.Set("state_clipboard",state.Call("copy_state",false));break;case "Paste as new state":var clipboard=session.Get("state_clipboard").As<Resource>();if(clipboard!=null&&!item.Get("locked").AsBool()){session.Call("begin");var copy=clipboard.Call("copy_state",true).As<Resource>();copy.Get("artwork").AsGodotObject().Set("id",item.Get("id"));item.Get("states").AsGodotArray().Add(copy);session.Get("edit_states").AsGodotDictionary()[item.Get("id")]=copy.Get("id");session.Call("commit","Paste state");}break;default:var states=item.Get("states").AsGodotArray();int index=states.IndexOf(state),target=Math.Clamp(index+(value=="Move state up"?-1:1),0,states.Count-1);if(target!=index&&!item.Get("locked").AsBool()){session.Call("begin");states.RemoveAt(index);states.Insert(target,state);session.Call("commit","Reorder state");}break;}});
    }
    public void component_menu(Control owner){Menu(owner,"COMPONENTS",new[]{"Duplicate","Copy","Paste","Delete","Import image as component…","Merge at playhead…"},value=>{var session=Session(owner);switch(value){case "Duplicate":session.Call("duplicate_components");break;case "Copy":session.Call("copy_components");break;case "Paste":session.Call("paste_components");break;case "Delete":session.Call("delete_components");break;case "Import image as component…":session.Call("add_component");owner.Call("import_dialog");break;case "Merge at playhead…":owner.Call("merge_at_playhead");break;}});}
    public void duration_dialog(Control owner){var popup=Attach(owner,new AcceptDialog {Title="Animation duration"});var input=Attach(popup,new SpinBox {MinValue=.05,MaxValue=86400,Step=.05,Value=Document(owner).Get("duration").AsDouble()});popup.Confirmed+=()=>{Session(owner).Call("set_duration",input.Value);popup.QueueFree();};popup.Canceled+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(300,100));}
    public void canvas_size_dialog(Control owner){var popup=Attach(owner,new AcceptDialog {Title="Canvas dimensions (artwork is preserved)"});var row=Attach(popup,new HBoxContainer());var inputs=new SpinBox[2];for(int axis=0;axis<2;axis++)inputs[axis]=Attach(row,new SpinBox {MinValue=1,MaxValue=8192,Value=Document(owner).Get("canvas_size").AsVector2I()[axis]});popup.Confirmed+=()=>{var size=new Vector2I((int)inputs[0].Value,(int)inputs[1].Value);if((long)size.X*size.Y<=16777216){Session(owner).Call("begin");Document(owner).Set("canvas_size",size);Session(owner).Call("commit","Canvas dimensions");Item<Control>(owner,"canvas").CallDeferred("fit");}else Status(owner,"Maximum canvas area is 16 megapixels.");popup.QueueFree();};popup.Canceled+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(360,100));}
    public void events_dialog(Control owner)
    {
        var popup=new PopupPanel();style_popup(popup);owner.AddChild(popup);var column=Attach(popup,new VBoxContainer {CustomMinimumSize=new Vector2(460,100)});Caption(column,"COMPONENT TRANSFERS · non-destructive / reversible");var scroll=Attach(column,new ScrollContainer {CustomMinimumSize=new Vector2(460,220)});var list=Attach(scroll,new VBoxContainer {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var events=Document(owner).Get("component_events").AsGodotArray();if(events.Count==0)Caption(list,"Detach selected pixels, or merge adjacent components at the playhead.");foreach(var raw in events){var entry=raw.AsGodotDictionary();string id=entry["id"].AsString();var row=Attach(list,new HBoxContainer());Caption(row,entry["kind"].AsString()+" → "+Document(owner).Call("component",entry["target"]).AsGodotObject().Get("title").AsString()).SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;NumberControl(owner,row,"Visibility time (s)",entry["time"].AsDouble(),0,Document(owner).Get("duration").AsDouble(),.01,value=>{foreach(var current in Document(owner).Get("component_events").AsGodotArray()){var item=current.AsGodotDictionary();if(item["id"].AsString()==id)item["time"]=value;}}).TooltipText="Retimes visibility only; captured artwork and poses are not re-baked.";Action(row,"⌫",()=>{remove_component_event(owner,id);popup.Hide();},"Remove transfer and hide its generated component; original drawings remain intact");}Action(column,"Done",()=>popup.Hide());popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(500,310));
    }
}
